import{_ as e,c as t,o,b0 as r}from"./chunks/framework.Dmsv_Tiv.js";const c="/media-docs/assets/image-20251220103531078.CQIzLTZi.png",u=JSON.parse('{"title":"LV040-TS封装简介","description":null,"frontmatter":{"title":"LV040-TS封装简介","date":"2025-12-20T10:03:56.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/vcodec/container/126b1ac7c50424bb8a2de8a3","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-12-20T10:03:56.587Z","fulluuid":"b8a2de8a3ee24cffad7be0b9f04187f1","useduuid":"b8a2de8a3"}},"headers":[],"relativePath":"sdoc/vcodec/container/126b1ac7c50424bb8a2de8a3.md","filePath":"sdoc/20-视频编解码/15-封装/LV040-TS封装简介.md","lastUpdated":1767537778000}'),l={name:"sdoc/vcodec/container/126b1ac7c50424bb8a2de8a3.md"};function n(d,a,s,i,p,S){return o(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="lv040-ts封装简介" tabindex="-1">LV040-TS封装简介 <a class="header-anchor" href="#lv040-ts封装简介" aria-label="Permalink to &quot;LV040-TS封装简介&quot;">​</a></h1><p>其实TS封装没怎么用过，这里简单了解一下，后续有需求再深入学习。</p><h2 id="一、ts-封装简介" tabindex="-1">一、TS 封装简介 <a class="header-anchor" href="#一、ts-封装简介" aria-label="Permalink to &quot;一、TS 封装简介&quot;">​</a></h2><p>TS 流 (Transport Stream)：传输流，TS 流由固定长度（188 字节）的 TS 包组成，TS 包是对 PES 包的另一种封装方式，同样由具有同一时间基准的一个或多个 PES 包复合合成。PS 包是不固定长度，而 TS 包为固定长度。</p><p>它是一种标准封装, 格式公开, 已被广泛应用于视音频资料的保存、电视节目的非线性编辑系统及其网络等方面。适合于在有可能发生严重错误的环境下进行一个或多个节目的编码数据的传送和存储。</p><p>TS 包以 4 个字节的前缀 (TS header) 开始, 包括位长 13bit 的 PID, 通过 PID 和节目特殊信息表(PSI)可以识别 TS 包中负载的内容。同一个 PID 值的 TS 包, 其负载只带有来自同一个原始流的数据。</p><h2 id="二、封装格式" tabindex="-1">二、封装格式 <a class="header-anchor" href="#二、封装格式" aria-label="Permalink to &quot;二、封装格式&quot;">​</a></h2><p>TS封装的结构示意图下所示：</p><p><img src="'+c+'" alt="image-20251220103531078"></p>',9)])])}const _=e(l,[["render",n]]);export{u as __pageData,_ as default};
